  ]
}

{
  "id": "R2",
  "summary_ko": "전구 유리의 모양이 변하고 오른쪽으로 떨어졌으며, 이는 실제로는 발생하지 않는 현상이다.",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "light bulb glass changed shape",
      "symptom_ko": "전구 유리의 형태가 변함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "light bulb glass",
      "explicit_detail_evidence": [
        "changed shape"
      ],
      "missing_details_ko": ""
    },
    {
      "id": "R2.S2",
      "evidence": "fell to the right side, this doesn't happen in real life",
      "symptom_ko": "오른쪽으로 떨어졌으며 실제로는 일어나지 않는 현상임",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "",
