  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "target_relation": "same",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The bulb starts to melt instead of burning out.",
      "candidate_evidence": "전구가 깜빡이지 않고 서서히 점등됨.",
      "basis": "explicit_separation",
      "reason_ko": "레퍼런스는 전구가 타서 꺼지는 대신 녹아내리는 물리적 파손/변형 결함('starts to melt instead of burning out')을 명시하고 있는 반면, 후보는 전구가 서서히 점등되는 발광/점등 동작 양상('깜빡이지 않고 서서히 점등됨')을 기술하고 있습니다. 동일한 대상(전구)에 대해 서로 완전히 다른 두 구체적 결함/현상을 기술하고 있으므로 명시적 분리에 해당합니다."
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "target_relation": "same",
      "reference_claim_ids": [
        "R2.S1",
        "R2.S2"
      ],
      "reference_evidence": "light bulb glass changed shape and fell to the right side",
      "candidate_evidence": "전구가 깜빡이지 않고 서서히 점등됨.",
      "basis": "explicit_separation",
      "reason_ko": "레퍼런스는 전구 유리의 물리적 형태 변형 및 오른쪽으로 떨어지는 물리적 결함 현상을 구체적으로 기술하고 있는 반면, 후보는 전구가 깜빡이지 않고 서서히 점등되는 발광/조명 상태만을 설명하여 명확히 구별되는 서로 다른 현상 및 결함에 관한 진술입니다."
    }
  ]
}

